const CACHE='margin-tide-1.1.0';
const CORE=['./','./index.html','./ink.css?v=1.1.0','./app.mjs?v=1.1.0','./model.mjs?v=1.1.0','./levels.mjs?v=1.1.0','./render.mjs?v=1.1.0','./audio.mjs?v=1.1.0','./storage.mjs?v=1.1.0','./prints.mjs?v=1.1.0','./assets/ink-atlas.webp','./assets/pigments.webp','./icon.svg','./icon-180.png','./icon-192.png','./icon-512.png','./manifest.webmanifest'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE&&(k.startsWith('margin-tide-')||k.startsWith('nocturne-eclipse-'))).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.open(CACHE).then(c=>c.match('./index.html'))));return;}const url=new URL(e.request.url);if(url.searchParams.get('v')==='1.1.0'||/\.(webp|png|svg|webmanifest)$/.test(url.pathname))e.respondWith(caches.open(CACHE).then(async c=>(await c.match(e.request))||fetch(e.request)));});
